    private function restoreMenuPreferences(): void
    {
        if (!$this->hasTable('sa_system_menu')) {
            return;
        }

        $preferences = [
            'Document' => ['name' => '官方文档', 'is_hidden' => 1, 'status' => 2],
            'Plugin' => ['name' => '插件市场', 'is_hidden' => 1, 'status' => 2],
            'Saiai' => ['name' => 'AI管理'],
            'Saiuser' => ['name' => '用户管理'],
            'cms/banner' => ['name' => '帮助轮播', 'is_hidden' => 1],
            'Saicode' => ['name' => 'SAICODE', 'is_hidden' => 1],
            'Saipay' => ['name' => 'SAIPAY', 'is_hidden' => 1],
            'Saisms' => ['name' => '短信管理'],
            'B8CMS' => ['name' => 'B8CMS', 'is_hidden' => 1],
        ];

        foreach ($preferences as $code => $fields) {
            $assignments = [];
            foreach ($fields as $field => $value) {
                $assignments[] = sprintf(
                    '`%s` = %s',
                    $field,
                    is_int($value) ? (string) $value : $this->quote($value)
                );
            }
            $assignments[] = '`update_time` = NOW()';

            $this->execute(sprintf(
                'UPDATE `sa_system_menu` SET %s WHERE `code` = %s AND `delete_time` IS NULL',
                implode(', ', $assignments),
                $this->quote($code)
            ));
        }
    }

    private function restoreExactRows(string $table, string $sql): void
    {
        if (!$this->hasTable($table) || trim($sql) === '') {
            return;
        }

        $this->executeSqlBatch($sql);
    }

    /**
     * @param list<string> $columns
     */
    private function restoreAuditRows(string $table, string $temporaryTable, array $columns, string $sql): void
    {
        if (!$this->hasTable($table) || trim($sql) === '') {
            return;
        }

        $tableSql = $this->identifier($table);
        $temporarySql = $this->identifier($temporaryTable);
        $this->execute(sprintf('DROP TEMPORARY TABLE IF EXISTS %s', $temporarySql));
        $this->execute(sprintf('CREATE TEMPORARY TABLE %s LIKE %s', $temporarySql, $tableSql));

        try {
            $this->executeSqlBatch($sql);

            $targetColumns = implode(', ', array_map(
                fn (string $column): string => $this->identifier($column),
                $columns
            ));
            $sourceColumns = implode(', ', array_map(
                fn (string $column): string => 's.' . $this->identifier($column),
                $columns
            ));
            $sameRow = implode(' AND ', array_map(
                fn (string $column): string => sprintf(
                    't.%1$s <=> s.%1$s',
                    $this->identifier($column)
                ),
                $columns
            ));

            $this->execute(sprintf(
                'INSERT INTO %1$s (%2$s)
                 SELECT %3$s
                 FROM %4$s AS s
                 WHERE NOT EXISTS (
                     SELECT 1 FROM %1$s AS t WHERE %5$s
                 )',
                $tableSql,
                $targetColumns,
                $sourceColumns,
                $temporarySql,
                $sameRow
            ));
        } finally {
            $this->execute(sprintf('DROP TEMPORARY TABLE IF EXISTS %s', $temporarySql));
        }
    }

    private function executeSqlBatch(string $sql): void
    {
        $statements = preg_split('/;\s*\R/', trim($sql)) ?: [];
        foreach ($statements as $statement) {
            if (trim($statement) !== '') {
                $this->execute($statement);
            }
        }
    }

    private function identifier(string $value): string
    {
        return '`' . str_replace('`', '``', $value) . '`';
    }

    private function quote(string $value): string
    {
        return $this->getAdapter()->getConnection()->quote($value);
    }
}
